-1024x584.jpg\";s:5:\"width\";i:1024;s:6:\"height\";i:584;s:9:\"mime-type\";s:10:\"image/jpeg\";}}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}}}'),(125,44,'_thumbnail_id','194'),(126,46,'_edit_last','1'),(127,46,'_edit_lock','1690379720:1'),(128,46,'_thumbnail_id','191'),(129,47,'_edit_last','1'),(130,47,'_edit_lock','1690379698:1'),(137,57,'_edit_last','1'),(138,57,'_edit_lock','1690380496:1'),(139,58,'_edit_last','1'),(140,58,'_edit_lock','1686594211:1'),(141,58,'_thumbnail_id','45'),(142,58,'_wp_page_template','default'),(143,60,'_edit_last','1'),(144,60,'_thumbnail_id','45'),(145,60,'_wp_page_template','default'),(146,60,'_edit_lock','1686593400:1'),(147,62,'_edit_last','1'),(148,62,'_wp_page_template','default'),(149,62,'_edit_lock','1686593495:1'),(150,62,'_thumbnail_id','45'),(151,64,'_edit_last','1'),(152,64,'_thumbnail_id','45'),(153,64,'_wp_page_template','default'),(154,64,'_edit_lock','1686594010:1'),(155,69,'_edit_last','1'),(156,69,'_thumbnail_id','45'),(157,69,'_wp_page_template','default'),(158,69,'_edit_lock','1686595667:1'),(159,71,'_edit_last','1'),(160,71,'_thumbnail_id','220'),(161,71,'_wp_page_template','default'),(162,71,'_edit_lock','1690380660:1'),(163,73,'_edit_last','1'),(164,73,'_thumbnail_id','45'),(165,73,'_wp_page_template','default'),(166,73,'_edit_lock','1686594334:1'),(167,75,'_edit_last','1'),(168,75,'_thumbnail_id','42'),(169,75,'_wp_page_template','default'),(170,75,'_edit_lock','1686761763:1'),(171,77,'_edit_last','1'),(172,77,'_thumbnail_id','202'),(173,77,'_wp_page_template','default'),(174,77,'_edit_lock','1690380587:1'),(175,79,'_edit_last','1'),(176,79,'_thumbnail_id','213'),(177,79,'_wp_page_template','default'),(178,79,'_edit_lock','1690380832:1'),(179,81,'_edit_last','1'),(180,81,'_thumbnail_id','191'),(181,81,'_wp_page_template','default'),(182,81,'_edit_lock','1690383436:1'),(183,57,'_thumbnail_id','200'),(184,57,'_wp_page_template','default'),(185,46,'image','191'),(186,46,'_image','field_647f5e3381dc1'),(187,46,'summary','ललितपुर महानगरपालिका वडा नं २४ ले नयाँ वर्ष २०८० को पहिलो महिना वडा भित्र बसोबास गर्ने एकल महिला तथा एकल पुरुष (ज्येष्ठ नागरिक) लाई दक्षिणकाली मन्दिर अवलोकन भ्रमणका लागि लगेको थियो । ज्येष्ठ नागरिकहरूलाई धार्मिक अवलोकन यात्राका लागि वडा कार्यालयले सहजीकरण गरेको हो । धार्मिक यात्रामा सहभागी ज्येष्ठ नागरिकहरूले वडा कार्यालयले आफूहरूलाई यस्ता कार्यक्रम आयोजना गरी सम्मान गरेको भन्दै जनप्रतिनिधिलाई धन्यवादसहित आर्शिवाद दिएका थिए । ‘बा–आमा भनेका जिउँदो देवता हुन् । वडा कार्यालयले आयोजना गरेको धार्मिक यात्रा कार्यक्रमले ती जिउँदो देवताको मुहारमा खुशी ल्याउन सकेको अनुभूति भएको छ’ वडाअध्यक्ष दिनेशजङग पाण्डेले ज्येष्ठ नागरिकको तीर्थयात्र पछि प्रतिक्रिया दिँदै भन्नुभयो । वडाबासीको मुहानमा हाँसो खुसी ल्याउन सक्दा आफू जनप्रतिनिधि भएर गरेको कार्यले सार्थकता पाएको वडाअध्यक्ष पाण्डेले बताउनुभयो । धार्मिक भ्रमण कार्यक्रमको संयोजन वडासदस्य उद्धब बस्नेतले गर्नु भएको थियो । वडाका ज्येष्ठ नागरिकहरूको एक दिने धार्मिक भ्रमण कार्यक्रमका प्रमुख अतिथि तथा वडाअध्यक्ष दिनेश जङ्ग पाण्डे रहनु भएको थियो । कार्यक्रममा विशेष अथितिका रूपमा बाबुकाजी प्रधान तथा वडासदस्यहरू हरिकृष्ण महर्जन, ईन्द्र श्रीश तथा वडा सदस्य निशा मालबुल अतिथिका रूपमा सहभागी हुनु भएको थियो । वडासचिव हर्कबहादुर अधिकारी, धापाखेल हेल्थपोष्टका कर्मचारी तथा महिला स्वस्थ स्वयम् सेविकाहरू पनि कार्यक्रममा सहभागी हुनु भएको थियो । यो कार्य सफल बनाउन वडासदस्य उद्धव बस्नेतसहितका वडाका जनप्रतिनिधि, वडासचिव तथा वडा कार्यालयका कर्मचारीको सक्रिय सहभागिता रहेको थियो । यस्तै वडाले ज्येष्ठ नागरिक, एकल महिला तथा एकल पुरुष अवलोकन भ्रमण तथा पौष्टिक आहार वितरण कार्यक्रम सम्पन्न गरेको छ । सामाजिक क्षेत्रको महिला–बालबालिका उपक्षेत्र शीर्षकमा आन्तरिक स्रोत परिचालन गरी ५ लाख रुपैयाँको लागतमा उक्त योजना सम्पन्न भएको हो ।'),(188,46,'_summary','field_647f5e4981dc2'),(189,46,'date','१'),(190,46,'_date','field_647f5e5d81dc3'),(191,46,'month','फागुन'),(192,46,'_month','field_647f5e8481dc4'),(193,84,'_edit_last','1'),(194,84,'image','190'),(195,84,'_image','field_647f5e3381dc1'),(196,84,'summary','२०७९ को लक्ष्मी पूजाको दिन ज्येष्ठ बा–आमाहरूको आशिर्वाद लिँदै वडाअध्यक्ष दिनेश जङ्ग पाण्डे  ...'),(197,84,'_summary','field_647f5e4981dc2'),(198,84,'date','१२'),(199,84,'_date','field_647f5e5d81dc3'),(200,84,'month','कार्तिक'),(201,84,'_month','field_647f5e8481dc4'),(202,84,'_edit_lock','1690304142:1'),(203,84,'_thumbnail_id','234'),(204,44,'image','194'),(205,44,'_image','field_647f5e3381dc1'),(206,44,'summary','ललितपुर महानगरपालिका वडा नं २४ को पहिचान भित्र पर्ने धार्मिक तथा पर्यटकीय स्थल नागदह क्षेत्रलाई सफा सुग्घर बनाउन वडा कार्यालयले विभिन्न समयमा सरसफाइका कार्यक्रम गर्दै आएको छ । यसै सन्दर्भमा धार्मिक स्थल नागदह वरिपरि सरसफÞाई कार्यक्रम आयोजना गरेको थियो । सरसफाई कार्यक्रममा वडाका जनप्रतिनिधि, महिला समूह, प्रहरी प्रशासनका प्रतिनिधिसहितका महानुभावको सक्रिय सहभागिता रहेको थियो । सरसफाई कार्यक्रमको शुभारम्भ गर्दै वडाअध्यक्ष दिनेशजङग पाण्डेले वडावासीलाई आफ्नो टोल–समुदायमा सबै मिलेर सरसफÞाई अभियान चलाउन आह्वान गर्नुभयो । आफ्नो टोल सफÞा सुन्दर राखेर असल नागरिकको परिचय दिन सबै वडावासी जिÞम्मेवारीपूर्वक लाग्नु पर्नेमा वडाका जनप्रतिनिधिले आह्वान गर्नु भएको थियो । सरसफाई कार्यक्रमका लागि आवश्यक सामग्रीको प्रबन्ध गर्न वडाकार्यालय सधैं वडावासीसँगै रहने प्रतिवद्धता पनि वडाका जनप्रतिनिधिहरूले व्यक्त गर्नु भएको थियो ।'),(207,44,'_summary','field_647f5e4981dc2'),(208,44,'date','९'),(209,44,'_date','field_647f5e5d81dc3'),(210,44,'month','मंसिर'),(211,44,'_month','field_647f5e8481dc4'),(212,85,'_edit_last','1'),(213,85,'_edit_lock','1690379684:1'),(214,87,'_edit_last','1'),(215,87,'_edit_lock','1690304784:1'),(216,87,'_thumbnail_id','198'),(217,87,'image','198'),(218,87,'_image','field_64876cc976dc7'),(219,89,'summary','साथै उहाँहरुको कलाकारिता संसारको अनेकन भूभागमा प्रतिस्थापित हुन सफल छन् । यसर्थ यस क्षेत्र हस्तकलाको जिवन्त स्थान हुनुले पनि यहाँ पुगेका पर्यटकहरु हर्षित हुने गर्दछ । यहाँ नेवार समूदायका विभिन्न जनजातिहरु मिलेर बसेका छन् भने धार्मिक सहिष्णुताले यस स्थानको मौलिक सभ्यता झनै सुन्दर भएको आभास पाउन सकिन्छ ।'),(220,89,'_summary','field_647efddcb86fc'),(221,89,'image','18'),(222,89,'_image','field_647efdf9b86fd'),(223,90,'summary','साथै उहाँहरुको कलाकारिता संसारको अनेकन भूभागमा प्रतिस्थापित हुन सफल छन् । यसर्थ यस क्षेत्र हस्तकलाको जिवन्त स्थान हुनुले पनि यहाँ पुगेका पर्यटकहरु हर्षित हुने गर्दछ । यहाँ नेवार समूदायका विभिन्न जनजातिहरु मिलेर बसेका छन् भने धार्मिक सहिष्णुताले यस स्थानको मौलिक सभ्यता झनै सुन्दर भएको आभास पाउन सकिन्छ ।'),(224,90,'_summary','field_647efddcb86fc'),(225,90,'image','18'),(226,90,'_image','field_647efdf9b86fd'),(227,91,'summary','साथै उहाँहरुको कलाकारिता संसारको अनेकन भूभागमा प्रतिस्थापित हुन सफल छन् । यसर्थ यस क्षेत्र हस्तकलाको जिवन्त स्थान हुनुले पनि यहाँ पुगेका पर्यटकहरु हर्षित हुने गर्दछ । यहाँ नेवार समूदायका विभिन्न जनजातिहरु मिलेर बसेका छन् भने धार्मिक सहिष्णुताले यस स्थानको मौलिक सभ्यता झनै सुन्दर भएको आभास पाउन सकिन्छ ।'),(228,91,'_summary','field_647efddcb86fc'),(229,91,'image','40'),(230,91,'_image','field_647efdf9b86fd'),(231,93,'_edit_last','1'),(232,93,'_edit_lock','1686761115:1'),(233,95,'image','34'),(234,95,'_image','field_6488b65446537'),(235,75,'image','34'),(236,75,'_image','field_6488b65446537'),(237,96,'image','34'),(238,96,'_image','field_6488b65446537'),(239,97,'image','34'),(240,97,'_image','field_6488b65446537'),(241,99,'image','34'),(242,99,'_image','field_6488b65446537'),(243,99,'summary','नेपालको इतिहासमा कीर्तिपुर एउटा आफ्नो छुट्टै अस्तित्वमा अगाडि बढिरहेको ऐतिहासिक नगर हो । नेवार जातिहरुको मुख्य बसोबास रहेको ऐतिहासिक कीर्तिपुर नगर वि.सं २०५३ चैत्र १४ गते'),(244,99,'_summary','field_6488bc3e158cb'),(245,75,'summary','ललितपुर महानगरपालिका वार्ड नं. २४ उत्तर पश्चिमी ललितपुरको एक प्रमुख वार्ड हो। यो वार्ड सुनौली, ठिमी, धोबी खोला, सनोपोखरी, घण्टे, गजुवा, बल्टी, गोलेगाउँ आदि गाउँहरूको भूभागलाई समावेश गर्दछ।\r\n\r\nयस वार्डमा विभिन्न जातिहरू, धर्महरू, भाषाहरू र संस्कृतिहरूको सम्मिश्रण देखिन्छ।\r\nयहाँका निवासीहरूले धेरै उच्च जातिका लागि जमिन खेती गर्ने काममा लगानी गर्दछन्। प्रमुख खेती उत्पादन धान, गहुँ, मकै, रातो आदि हुन्छ।\r\n\r\n                        यस वार्डमा विभिन्न धार्मिक स्थलहरू पाइन्छन्। प्रमुख मन्दिरहरूमा रामजन्मभूमि मन्दिर, चंडेश्वरी मन्दिर, तालेश्वरी मन्दिर, धुपेश्वरी मन्दिर, गुरुङदेव मन्दिर, भैरवनाथ मन्दिर, कालभैरव मन्दिर आदि छन्। यहाँमा प्रतिवर्ष विभिन्न धार्मिक उत्सवहरू मनाइन्छन् जुन धार्मिक अनुयायहरूले समेटेर साथ मनाउने हुन्छ।\r\n\r\n                        ललितपुर महानगरपालिका वार्ड नं. २४ शहरी विक'),(246,75,'_summary','field_6488bc3e158cb'),(247,100,'image','34'),(248,100,'_image','field_6488b65446537'),(249,100,'summary','नेपालको इतिहासमा कीर्तिपुर एउटा आफ्नो छुट्टै अस्तित्वमा अगाडि बढिरहेको ऐतिहासिक नगर हो । नेवार जातिहरुको मुख्य बसोबास रहेको ऐतिहासिक कीर्तिपुर नगर वि.सं २०५३ चैत्र १४ गते तत्कालिन आठ गा.वि.स. हरु (लायकु, चिठु बिहार, पालिफल, बाहिरी गाउँ, पाँगा विष्णुदेवी, पाँगा बालकुमारी, चोभार भुतखेल र चम्पादेवी) गाभेर नगरपालिका ऐन, २०४८ अनुसार गठन भएको हो । मल्ल कालदेखि नै कला र संस्कृतिले धनी यस कीर्तिपुर नगरले आधुनिक नेपालको निर्माण गर्ने क्रममा हरेक पाईलामा भाग लिंदै आईरहेको छ । अर्को तिर प्रत्येक प्रजातान्त्रिक आन्दोलनमा कीर्तिपुरले उल्लेखनिय भूमिका खेल्दै आएको छ ।'),(250,100,'_summary','field_6488bc3e158cb'),(251,101,'image','34'),(252,101,'_image','field_6488b65446537'),(253,101,'summary','ललितपुर महानगरपालिका वार्ड नं. २४ उत्तर पश्चिमी ललितपुरको एक प्रमुख वार्ड हो। यो वार्ड सुनौली, ठिमी, धोबी खोला, सनोपोखरी, घण्टे, गजुवा, बल्टी, गोलेगाउँ आदि गाउँहरूको भूभागलाई समावेश गर्दछ।\r\n\r\nयस वार्डमा विभिन्न जातिहरू, धर्महरू, भाषाहरू र संस्कृतिहरूको सम्मिश्रण देखिन्छ।\r\nयहाँका निवासीहरूले धेरै उच्च जातिका लागि जमिन खेती गर्ने काममा लगानी गर्दछन्। प्रमुख खेती उत्पादन धान, गहुँ, मकै, रातो आदि हुन्छ।\r\n\r\n                        यस वार्डमा विभिन्न धार्मिक स्थलहरू पाइन्छन्। प्रमुख मन्दिरहरूमा रामजन्मभूमि मन्दिर, चंडेश्वरी मन्दिर, तालेश्वरी मन्दिर, धुपेश्वरी मन्दिर, गुरुङदेव मन्दिर, भैरवनाथ मन्दिर, कालभैरव मन्दिर आदि छन्। यहाँमा प्रतिवर्ष विभिन्न धार्मिक उत्सवहरू मनाइन्छन् जुन धार्मिक अनुयायहरूले समेटेर साथ मनाउने हुन्छ।\r\n\r\n                        ललितपुर महानगरपालिका वार्ड नं. २४ शहरी विक'),(254,101,'_summary','field_6488bc3e158cb'),(255,102,'_edit_last','1'),(256,102,'_edit_lock','1686764369:1'),(265,107,'_wp_attached_file','2023/06/chairperson.jpg'),(266,107,'_wp_attachment_metadata','a:5:{s:5:\"width\";i:1500;s:6:\"height\";i:1000;s:4:\"file\";s:23:\"2023/06/chairperson.jpg\";s:5:\"sizes\";a:4:{s:9:\"thumbnail\";a:4:{s:4:\"file\";s:23:\"chairperson-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";}s:6:\"medium\";a:4:{s:4:\"file\";s:23:\"chairperson-300x200.jpg\";s:5:\"width\";i:300;s:6:\"height\";i:200;s:9:\"mime-type\";s:10:\"image/jpeg\";}s:12:\"medium_large\";a:4:{s:4:\"file\";s:23:\"chairperson-768x512.jpg\";s:5:\"width\";i:768;s:6:\"height\";i:512;s:9:\"mime-type\";s:10:\"image/jpeg\";}s:5:\"large\";a:4:{s:4:\"file\";s:24:\"chairperson-1024x683.jpg\";s:5:\"width\";i:1024;s:6:\"height\";i:683;s:9:\"mime-type\";s:10:\"image/jpeg\";}}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}}}'),(274,109,'_edit_last','1'),(275,109,'_edit_lock','1690298453:1'),(276,109,'_thumbnail_id','213'),(277,109,'_wp_page_template','default'),(279,111,'_menu_item_type','post_type'),(280,111,'_menu_item_menu_item_parent','0'),(281,111,'_menu_item_object_id','109'),(282,111,'_menu_item_object','page'),(283,111,'_menu_item_target',''),(284,111,'_menu_item_classes','a:1:{i:0;s:0:\"\";}'),(285,111,'_menu_item_xfn',''),(286,111,'_menu_item_url',''),(287,111,'_menu_item_orphaned','1686765370'),(288,112,'_menu_item_ty