.टोली तृतीय\r\n                    भएको थियो । ......सान्त्वना भएको उक्त\r\n                    प्रतियोगितामा विजयी टोलीलाई क्रमश\r\n                    ः .......का दरले नगद तथा शील्ड प्रदान\r\n                    गरिएको थियो ।'),(475,148,'_summary','field_648b41ecaeb7e'),(476,148,'date','२५'),(477,148,'_date','field_648b4207aeb7f'),(478,148,'month','चैत्र'),(479,148,'_month','field_648b4213aeb80'),(480,148,'year','२०८० '),(481,148,'_year','field_648b449fe338a'),(485,148,'_thumbnail_id','220'),(486,152,'_edit_last','1'),(487,152,'_aigpl_gallery_imgs','a:22:{i:0;s:2:\"38\";i:1;s:3:\"215\";i:2;s:3:\"220\";i:3;s:3:\"217\";i:4;s:3:\"216\";i:5;s:3:\"214\";i:6;s:3:\"213\";i:7;s:3:\"212\";i:8;s:3:\"211\";i:9;s:3:\"210\";i:10;s:3:\"209\";i:11;s:3:\"208\";i:12;s:3:\"206\";i:13;s:3:\"204\";i:14;s:3:\"202\";i:15;s:3:\"200\";i:16;s:3:\"198\";i:17;s:3:\"196\";i:18;s:3:\"194\";i:19;s:3:\"191\";i:20;s:3:\"190\";i:21;s:3:\"183\";}'),(488,152,'_edit_lock','1690298834:1'),(489,152,'_thumbnail_id','191'),(490,154,'_form','<form_div>\n<div class=\"form-group\">\n    [text* fullname id:name placeholder \"पूरा नाम\"]\n</div>\n\n<div class=\"form-group\">\n    [email* email id:email placeholder \"इमेल\"]\n</div>\n\n<div class=\"form-group\">\n    [textarea* message id:message placeholder \"सन्देश\"]\n</div>\n<div class=\"btn_wrap\">\n    [submit class:submit-btn class:btn-success class:px-5 \"पठाउनुस\"]\n</div>\n         </form_div>'),(491,154,'_mail','a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:23:\"ward24 \"[your-subject]\"\";s:6:\"sender\";s:34:\"[your-name] <kjhasachin@gmail.com>\";s:9:\"recipient\";s:20:\"kjhasachin@gmail.com\";s:4:\"body\";s:171:\"From: [your-name] <[your-email]>\nSubject: [your-subject]\n\nMessage Body:\n[your-message]\n\n-- \nThis e-mail was sent from a contact form on ward24 (http://localhost/ward24_db)\";s:18:\"additional_headers\";s:22:\"Reply-To: [your-email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),(492,154,'_mail_2','