'),(636,184,'_designation','field_6489f3aa8527d'),(637,184,'phone_number','० १ -२ १०२० ३१'),(638,184,'_phone_number','field_6489f3e98527e'),(639,185,'summary','साथै उहाँहरुको कलाकारिता संसारको अनेकन भूभागमा प्रतिस्थापित हुन सफल छन् । यसर्थ यस क्षेत्र हस्तकलाको जिवन्त स्थान हुनुले पनि यहाँ पुगेका पर्यटकहरु हर्षित हुने गर्दछ । यहाँ नेवार समूदायका विभिन्न जनजातिहरु मिलेर बसेका छन् भने धार्मिक सहिष्णुताले यस स्थानको मौलिक सभ्यता झनै सुन्दर भएको आभास पाउन सकिन्छ ।'),(640,185,'_summary','field_647efddcb86fc'),(641,185,'image','40'),(642,185,'_image','field_647efdf9b86fd'),(643,187,'summary','हाम्रो पहिचान’ भन्ने नारा बोकेको यस\r\nवडाको मुल थलोको रुपमा नागदह\r\nर आँखीदह रहेका छन् । यस\r\nवडाको चारैतिर मनोरम दृश्य देख्न\r\nपाइन्छ । वडा नं २४ मा जल्पादेवी\r\nमावि, वालोदय आधारभूत विद्यालय,\r\nकल्याण बोर्डिङ स्कुल, सूर्याेदय बोर्डिङ\r\nस्कुल, धापाखेल बोर्डिङ स्कुल, न्यू\r\nमोडन बोर्डिङ स्कुल छन् । वडावासीको\r\nउपचार तथा स्वास्थ्य परामर्शका\r\nलागि २४ नं वडामा मस्तिष्क\r\nपक्षघात स्याहार केन्द्र, धापाखेल\r\nहेल्थपोष्ट रहेको छ । नागदह, आँखीदह,\r\nगौखुरेश्वर महादेव मन्दिर, नवलिङ्गेश्वर\r\nमहादेव मन्दिर, गणेशमन्दिर, जाल्पादेवी\r\nमन्दिर÷धर्मशाला, पशुपति मन्दिर,\r\nसेतागणेश मन्दिर, विषनदेवी मन्दिर,\r\nसेताभैरव मन्दिर जस्ता सम्पदा\r\nतथा पर्यटकीय स्थलले ललितपुर\r\nमहानगरपालिका वडा नं २४ लाई\r\nमनमोहक बनाएको छ ।\r\nयो वडामा मुख्यगरी भण्डारी टोल,\r\nसुब्बा टोल, बिसनदेवी टोल, भीमसेन\r\nपिपलबोट टोल, नागदह टोल, ढुङ्गे\r\nगल्ली टोल, प्रधान टोल, भगवती टोल,\r\nगिरि टोल, प्रगति टोल, समावेशी टोल,\r\nपशुपति टोल, माली टोल, सेताभैरव\r\nटोल, बाँसघारी टोल, चौतारा टोल,\r\nदाघाट टोल र बाहुनगाँउ टोल गरी १८\r\nटोलमा विभाजन गरिएको छ ।'),(644,187,'_summary','field_647efddcb86fc'),(645,187,'image','40'),(646,187,'_image','field_647efdf9b86fd'),(647,188,'summary','हाम्रो पहिचान’ भन्ने नारा बोकेको यस वडाको मुल थलोको रुपमा नागदह र आँखीदह रहेका छन् । यस वडाको चारैतिर मनोरम दृश्य देख्न पाइन्छ । वडा नं २४ मा जल्पादेवी मावि, वालोदय आधारभूत विद्यालय, कल्याण बोर्डिङ स्कुल, सूर्योदय बोर्डिङ स्कुल, धापाखेल बोर्डिङ स्कुल, न्यू मोडन बोर्डिङ स्कुल छन् ।'),(648,188,'_summary','field_647efddcb86fc'),(649,188,'image','40'),(650,188,'_image','field_647efdf9b86fd'),(651,190,'_wp_attached_file','2023/06/news01-1.jpg'),(652,190,'_wp_attachment_metadata','a:5:{s:5:\"width\";i:802;s:6:\"height\";i:405;s:4:\"file\";s:20:\"2023/06/news01-1.jpg\";s:5:\"sizes\";a:3:{s:9:\"thumbnail\";a:4:{s:4:\"file\";s:20:\"news01-1-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";}s:6:\"medium\";a:4:{s:4:\"file\";s:20:\"news01-1-300x151.jpg\";s:5:\"width\";i:300;s:6:\"height\";i:151;s:9:\"mime-type\";s:10:\"image/jpeg\";}s:12:\"medium_large\";a:4:{s:4:\"file\";s:20:\"news01-1-768x388.jpg\";s:5:\"width\";i:768;s:6:\"height\";i:388;s:9:\"mime-type\";s:10:\"image/jpeg\";}}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}}}'),(653,191,'_wp_attached_file','2023/06/news02.jpg'),(654,191,'_wp_attachment_metadata','a:5:{s:5:\"width\";i:1223;s:6:\"height\";i:700;s:4:\"file\";s:18:\"2023/06/news02.jpg\";s:5:\"sizes\";a:4:{s:9:\"thumbnail\";a:4:{s:4:\"file\";s:18:\"news02-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";}s:6:\"medium\";a:4:{s:4:\"file\";s:18:\"news02-300x172.jpg\";s:5:\"width\";i:300;s:6:\"height\";i:172;s:9:\"mime-type\";s:10:\"image/jpeg\";}s:12:\"medium_large\";a:4:{s:4:\"file\";s:18:\"news02-768x440.jpg\";s:5:\"width\";i:768;s:6:\"height\";i:440;s:9:\"mime-type\";s:10:\"image/jpeg\";}s:5:\"large\";a:4:{s:4:\"file\";s:19:\"news02-1024x586.jpg\";s:5:\"width\";i:1024;s:6:\"height\";i:586;s:9:\"mime-type\";s:10:\"image/jpeg\";}}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camer