intro_text','ai_text'),(1602,253,'intro_image_url','https://images.unsplash.com/photo-1541888946425-d81bb19240f5?auto=format&fit=crop&w=1200&q=80'),(1603,253,'_intro_image_url','ai_img_url'),(1604,253,'intro_badge_number','Since 2015'),(1605,253,'_intro_badge_number','ai_bn'),(1606,253,'intro_badge_label','Serving Nepal'),(1607,253,'_intro_badge_label','ai_bl'),(1608,253,'intro_stats','4'),(1609,253,'_intro_stats','ai_stats'),(1610,253,'mv_eyebrow','Direction'),(1611,253,'_mv_eyebrow','mv_eyebrow'),(1612,253,'mv_title','Mission & Vision'),(1613,253,'_mv_title','mv_title'),(1614,253,'mv_sub','Where we are going, and how we intend to get there.'),(1615,253,'_mv_sub','mv_sub'),(1616,253,'mv_cards_0_icon','bi-bullseye'),(1617,253,'_mv_cards_0_icon','mv_c_i'),(1618,253,'mv_cards_0_title','Our Mission'),(1619,253,'_mv_cards_0_title','mv_c_t'),(1620,253,'mv_cards_0_text','To make property decisions in Nepal simpler and safer — by verifying every listing before it reaches a client, quoting honestly, and standing behind the buildings we put our name on. We would rather lose a deal than sell a property we would not buy ourselves.'),(1621,253,'_mv_cards_0_text','mv_c_x'),(1628,253,'mv_cards','2'),(1629,253,'_mv_cards','mv_cards'),(1648,253,'team_cards_1_image_url','https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=1200&q=80'),(1649,253,'_team_cards_1_image_url','at_i'),(1650,253,'team_cards_1_title','Sunita Karki'),(1651,253,'_team_cards_1_title','at_t'),(1652,253,'team_cards_1_role','Head of Property Consultancy'),(1653,253,'_team_cards_1_role','at_role'),(1654,253,'team_cards_1_text',''),(1655,253,'_team_cards_1_text','at_x'),(1656,253,'team_cards_2_image_url','https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=1200&q=80'),(1657,253,'_team_cards_2_image_url','at_i'),(1658,253,'team_cards_2_title','Bikash Shrestha'),(1659,253,'_team_cards_2_title','at_t'),(1660,253,'team_cards_2_role','Senior Structural Engine