INSERT INTO `st_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1,1,'2023-06-06 05:58:04','2023-06-06 05:58:04','Welcome to WordPress. This is your first post. Edit or delete it, then start writing!','Hello world!','','publish','open','open','','hello-world','','','2023-06-06 05:58:04','2023-06-06 05:58:04','',0,'http://localhost/ward24_db/?p=1',0,'post','',1),(2,1,'2023-06-06 05:58:04','2023-06-06 05:58:04','This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:\r\n\r\n<blockquote>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</blockquote>\r\n\r\n...or something like this:\r\n\r\n<blockquote>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</blockquote>\r\n\r\nAs a new WordPress user, you should go to <a href=\"http://localhost/ward24_db/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!','Sample Page','','publish','closed','open','','sample-page','','','2023-06-06 05:58:04','2023-06-06 05:58:04','',0,'http://localhost/ward24_db/?page_id=2',0,'page','',0),(3,1,'2023-06-06 05:58:04','2023-06-06 05:58:04','<h2>Who we are</h2><p>Our website address is: http://localhost/ward24_db.</p><h2>What personal data we collect and why we collect it</h2><h3>Comments</h3><p>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p><p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p><h3>Media</h3><p>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p><h3>Contact forms</h3><h3>Cookies</h3><p>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p><p>If you have an account and you log in to this site, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p><p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p><p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p><h3>Embedded content from other websites</h3><p>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p><p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p><h3>Analytics</h3><h2>Who we share your data with</h2><h2>How long we retain your data</h2><p>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p><p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p><h2>What rights you have over your data</h2><p>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p><h2>Where we send your data</h2><p>Visitor comments may be checked through an automated spam detection service.</p><h2>Your contact information</h2><h2>Additional information</h2><h3>How we protect your data</h3><h3>What data breach procedures we have in place</h3><h3>What third parties we receive data from</h3><h3>What automated decision making and/or profiling we do with user data</h3><h3>Industry regulatory disclosure requirements</h3>','Privacy Policy','','draft','closed','open','','privacy-policy','','','2023-06-06 05:58:04','2023-06-06 05:58:04','',0,'http://localhost/ward24_db/?page_id=3',0,'page','',0),(10,1,'2023-06-06 08:30:49','0000-00-00 00:00:00','','Home','','draft','closed','closed','','','','','2023-06-06 08:30:49','0000-00-00 00:00:00','',0,'http://localhost/ward24_db/?p=10',1,'nav_menu_item','',0),(11,1,'2023-06-06 08:30:49','0000-00-00 00:00:00',' ','','','draft','closed','closed','','','','','2023-06-06 08:30:49','0000-00-00 00:00:00','',0,'http://localhost/ward24_db/?p=11',1,'nav_menu_item','',0),(12,1,'2023-06-06 08:33:52','2023-06-06 08:33:52','','गृहपृष्ठ','','publish','closed','closed','','%e0%a4%97%e0%a5%83%e0%a4%b9%e0%a4%aa%e0%a5%83%e0%a4%b7%e0%a5%8d%e0%a4%a0','','','2023-06-06 08:33:52','2023-06-06 08:33:52','',0,'http://localhost/ward24_db/?p=12',1,'nav_menu_item','',0),(13,1,'2023-06-06 08:31:42','0000-00-00 00:00:00',' ','','','draft','closed','closed','','','','','2023-06-06 08:31:42','0000-00-00 00:00:00','',0,'http://localhost/ward24_db/?p=13',1,'nav_menu_item','',0),(14,1,'2023-06-06 08:46:09','2023-06-06 08:46:09','a:7:{s:8:\"location\";a:1:{i:0;a:1:{i:0;a:3:{s:5:\"param\";s:13:\"page_template\";s:8:\"operator\";s:2:\"==\";s:5:\"value\";s:13:\"main-page.php\";}}}s:8:\"position\";s:6:\"normal\";s:5:\"style\";s:7:\"default\";s:15:\"label_placement\";s:3:\"top\";s:21:\"instruction_placement\";s:5:\"label\";s:14:\"hide_on_screen\";s:0:\"\";s:11:\"description\";s:0:\"\";}','Home','home','publish','closed','closed','','group_647ef1fae3710','','','2023-06-06 08:46:09','2023-06-06 08:46:09','',0,'http://localhost/ward24_db/?post_type=acf-field-group&#038;p=14',0,'acf-field-group','',0),(15,1,'2023-06-06 08:46:09','2023-06-06 08:46:09','a:17:{s:4:\"type\";s:7:\"gallery\";s:12:\"instructions\";s:0:\"\";s:8:\"required\";i:0;s:17:\"conditional_logic\";i:0;s:7:\"wrapper\";a:3:{s:5:\"width\";s:0:\"\";s:5:\"class\";s:0:\"\";s:2:\"id\";s:0:\"\";}s:3:\"min\";s:0:\"\";s:3:\"max\";s:0:\"\";s:12:\"preview_size\";s:9:\"thumbna